Item.method_code:
const { itemTypeName, itemId } = options;
const isNew = ArasModules.item.getChanges(itemTypeName, itemId)
	? ArasModules.item.isNew(itemTypeName, itemId)
	: window.item.getAttribute('action') === 'add';
const isCurrentVersion =
	aras.getItemProperty(window.item, 'is_current') === '1';

if (isNew || isCurrentVersion) {
	return {
		hidden: true
	};
}

const label = aras.getResource('', 'version.open_current');

return {
	type: 'link',
	label
};
